create or replace function public.ce_create_decision_mission(p_decision_id uuid,p_diagnosis text,p_recommendation text,p_confidence numeric,p_priority text,p_evidence jsonb,p_mission_id uuid,p_objective text,p_state text,p_kpi text,p_engine_version text,p_p1r numeric,p_p2r numeric,p_p3r numeric,p_expected_r numeric,p_risk_gate text,p_prediction_source text,p_calibration_status text) returns jsonb language plpgsql security definer set search_path=public as $$begin insert into ce_decisions(id,diagnosis,recommendation,confidence,priority,evidence,engine_version)values(p_decision_id,p_diagnosis,p_recommendation,p_confidence,p_priority,p_evidence,p_engine_version);insert into ce_missions(id,decision_id,objective,state,kpi)values(p_mission_id,p_decision_id,p_objective,p_state,p_kpi);insert into ce_events(mission_id,decision_id,event_type,to_state,actor_type)values(p_mission_id,p_decision_id,'MISSION_CREATED',p_state,'system');insert into ce_prediction_ledger(decision_id,mission_id,engine_version,p1r,p2r,p3r,expected_r,risk_gate,prediction_source,calibration_status)values(p_decision_id,p_mission_id,p_engine_version,p_p1r,p_p2r,p_p3r,p_expected_r,p_risk_gate,p_prediction_source,p_calibration_status);return jsonb_build_object('mission_id',p_mission_id,'decision_id',p_decision_id);end;$$;
create or replace function public.ce_transition_mission(p_mission_id uuid,p_next_state text,p_actor_type text) returns jsonb language plpgsql security definer set search_path=public as $$declare m ce_missions%rowtype;begin select * into m from ce_missions where id=p_mission_id for update;if not found then raise exception 'MISSION_NOT_FOUND';end if;if not ((m.state='AWAITING_APPROVAL' and p_next_state in('APPROVED','REJECTED','EXPIRED'))or(m.state='APPROVED' and p_next_state in('EXECUTING','REJECTED'))or(m.state='EXECUTING' and p_next_state in('MEASURING','FAILED'))or(m.state='MEASURING' and p_next_state in('COMPLETED','FAILED'))or(m.state='COMPLETED' and p_next_state='LEARNED')or(m.state='FAILED' and p_next_state in('EXECUTING','REJECTED'))) then raise exception 'INVALID_TRANSITION';end if;update ce_missions set state=p_next_state,execution_count=execution_count+case when p_next_state='EXECUTING' then 1 else 0 end,updated_at=now() where id=p_mission_id;insert into ce_events(mission_id,decision_id,event_type,from_state,to_state,actor_type)values(p_mission_id,m.decision_id,'STATE_CHANGED',m.state,p_next_state,p_actor_type);return jsonb_build_object('mission_id',m.id,'decision_id',m.decision_id,'from_state',m.state,'to_state',p_next_state,'execution_count',m.execution_count+case when p_next_state='EXECUTING' then 1 else 0 end);end;$$;
create or replace function public.ce_record_mission_outcome(p_mission_id uuid,p_event_type text,p_metadata jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare m ce_missions%rowtype;begin select * into m from ce_missions where id=p_mission_id;if not found then raise exception 'MISSION_NOT_FOUND';end if;insert into ce_events(mission_id,decision_id,event_type,to_state,actor_type,metadata)values(m.id,m.decision_id,p_event_type,m.state,'system',p_metadata);return jsonb_build_object('mission_id',m.id,'event_type',p_event_type,'state',m.state);end;$$;
create or replace function public.ce_record_learning(p_mission_id uuid,p_lesson_type text,p_quality text,p_improved boolean,p_delta numeric,p_delta_pct numeric,p_lesson text,p_reason text) returns jsonb language plpgsql security definer set search_path=public as $$declare x uuid:=gen_random_uuid();m ce_missions%rowtype;begin select * into m from ce_missions where id=p_mission_id;if not found then raise exception 'MISSION_NOT_FOUND';end if;insert into ce_learning(id,mission_id,lesson_type,quality,improved,delta,delta_pct,lesson,reason)values(x,p_mission_id,p_lesson_type,p_quality,p_improved,p_delta,p_delta_pct,p_lesson,p_reason);return jsonb_build_object('learning_id',x,'mission_id',p_mission_id,'decision_id',m.decision_id,'lesson_type',p_lesson_type,'quality',p_quality,'lesson',p_lesson);end;$$;
create or replace function public.ce_resolve_prediction(p_mission_id uuid,p_realized_r numeric,p_outcome_status text,p_outcome_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$begin update ce_prediction_ledger set realized_r=p_realized_r,outcome_status=p_outcome_status,outcome_payload=p_outcome_payload,resolved_at=now() where mission_id=p_mission_id;return jsonb_build_object('mission_id',p_mission_id,'outcome_status',p_outcome_status);end;$$;
revoke all on function public.ce_create_decision_mission(uuid,text,text,numeric,text,jsonb,uuid,text,text,text,text,numeric,numeric,numeric,numeric,text,text,text) from public,anon,authenticated;grant execute on function public.ce_create_decision_mission(uuid,text,text,numeric,text,jsonb,uuid,text,text,text,text,numeric,numeric,numeric,numeric,text,text,text) to service_role;
revoke all on function public.ce_transition_mission(uuid,text,text) from public,anon,authenticated;grant execute on function public.ce_transition_mission(uuid,text,text) to service_role;
revoke all on function public.ce_record_mission_outcome(uuid,text,jsonb) from public,anon,authenticated;grant execute on function public.ce_record_mission_outcome(uuid,text,jsonb) to service_role;
revoke all on function public.ce_record_learning(uuid,text,text,boolean,numeric,numeric,text,text) from public,anon,authenticated;grant execute on function public.ce_record_learning(uuid,text,text,boolean,numeric,numeric,text,text) to service_role;
revoke all on function public.ce_resolve_prediction(uuid,numeric,text,jsonb) from public,anon,authenticated;grant execute on function public.ce_resolve_prediction(uuid,numeric,text,jsonb) to service_role;
